{
  "name": "@vigolium/piolium",
  "version": "0.0.13",
  "description": "Multi-phase security audits with specialist sub-agents, isolated context windows, capped concurrency, and resumable state — packaged as a Pi extension.",
  "keywords": [
    "pi-package",
    "pi-extension",
    "security",
    "audit",
    "subagents",
    "piolium"
  ],
  "license": "MIT",
  "homepage": "https://github.com/vigolium/piolium",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/vigolium/piolium.git"
  },
  "bugs": {
    "url": "https://github.com/vigolium/piolium/issues"
  },
  "type": "module",
  "bin": {
    "piolium": "./bin/piolium.mjs"
  },
  "pi": {
    "extensions": [
      "./extensions/piolium/index.ts"
    ],
    "skills": [
      "./skills"
    ],
    "prompts": [
      "./prompts"
    ],
    "themes": [
      "./themes"
    ]
  },
  "peerDependencies": {
    "@anthropic-ai/vertex-sdk": "^0.14.0",
    "@earendil-works/pi-ai": "^0.74.0",
    "@earendil-works/pi-agent-core": "^0.74.0",
    "@earendil-works/pi-coding-agent": "^0.74.0",
    "@earendil-works/pi-tui": "^0.74.0",
    "@earendil-works/pi-web-ui": "^0.74.0",
    "typebox": "^1.1.24"
  },
  "peerDependenciesMeta": {
    "@anthropic-ai/vertex-sdk": {
      "optional": true
    },
    "@earendil-works/pi-ai": {
      "optional": true
    },
    "@earendil-works/pi-agent-core": {
      "optional": true
    },
    "@earendil-works/pi-coding-agent": {
      "optional": true
    },
    "@earendil-works/pi-tui": {
      "optional": true
    },
    "@earendil-works/pi-web-ui": {
      "optional": true
    },
    "typebox": {
      "optional": true
    }
  },
  "engines": {
    "bun": ">=1.1.0"
  },
  "files": [
    "bin/",
    "extensions/",
    "skills/",
    "prompts/",
    "themes/",
    "agents/",
    "docs/",
    "README.md",
    "LICENSE"
  ],
  "publishConfig": {
    "access": "public"
  }
}
